#pragma once
// Palette entries for the real-time sound-graph nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after
// pin()/attr() are defined, and calls appendProceduralSoundNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphProceduralSoundNodeTable.cs pin for pin (docs/AUDIO.md section 13). sound= is the .ocsnd path,
// param= the Parameter node's name in it. Buses: 0 Sfx, 1 Music, 2 Voice, 3 Ui. The voice pin works with the audio-control nodes too.

inline void appendProceduralSoundNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_PlaySoundGraph", "Play Sound Graph", "Audio", {
        pin("exec", "exec", false), pin("volume", "float", false, "1"), pin("looping", "bool", false), pin("bus", "int", false), pin("seed", "int", false),
        pin("then", "exec", true), pin("voice", "int", true), pin("success", "bool", true)},
        {attr("sound", "Sound Graph")}});
    t.push_back({"AN_PlaySoundGraphAt", "Play Sound Graph At", "Audio", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false), pin("volume", "float", false, "1"),
        pin("looping", "bool", false), pin("bus", "int", false), pin("innerCm", "float", false, "200"), pin("outerCm", "float", false, "2000"), pin("seed", "int", false),
        pin("then", "exec", true), pin("voice", "int", true), pin("success", "bool", true)},
        {attr("sound", "Sound Graph")}});
    t.push_back({"AN_SetSoundGraphParam", "Set Sound Graph Input", "Audio", {
        pin("exec", "exec", false), pin("voice", "int", false), pin("value", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)},
        {attr("param", "Input Name")}});
    t.push_back({"AN_NoteOffSoundGraph", "Note Off Sound Graph", "Audio", {
        pin("exec", "exec", false), pin("voice", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
}
